@@ -17,34 +17,101 @@
   readonly #entries = new Map<string, Entry<V>>();

   constructor(options: CacheOptions) {
-    throw new Error("not implemented");
+    if (options.ttlMs <= 0) {
+      throw new RangeError("ttlMs must be positive");
+    }
+    if (options.maxEntries !== undefined && (!Number.isInteger(options.maxEntries) || options.maxEntries <= 0)) {
+      throw new RangeError("maxEntries must be a positive integer");
+    }
+    this.#ttlMs = options.ttlMs;
+    this.#maxEntries = options.maxEntries;
+    this.#now = options.now ?? Date.now;
   }

   set(key: string, value: V, ttlMs?: number): void {
-    throw new Error("not implemented");
+    if (ttlMs !== undefined && ttlMs <= 0) {
+      throw new RangeError("ttlMs must be positive");
+    }
+    
+    const expiresAt = this.#now() + (ttlMs ?? this.#ttlMs);
+    this.#entries.set(key, { value, expiresAt });
+    
+    // Handle maxEntries constraint
+    if (this.#maxEntries !== undefined && this.#entries.size > this.#maxEntries) {
+      // Find the oldest entry (earliest expiresAt)
+      let oldestKey: string | undefined;
+      let oldestExpiresAt = Infinity;
+      
+      for (const [k, entry] of this.#entries.entries()) {
+        if (entry.expiresAt < oldestExpiresAt) {
+          oldestExpiresAt = entry.expiresAt;
+          oldestKey = k;
+        }
+      }
+      
+      if (oldestKey !== undefined) {
+        this.#entries.delete(oldestKey);
+      }
+    }
